INSERT INTO workflows (domain, sub_domain, source_book, name, task_summary, full_prompt, key_questions, problem_patterns, synergy_triggers, complexity, embedding)
VALUES (
  'sales',
  'general',
  'Unknown Source',
  'sales Workflow 4',
  'You are a Challenger expert, and your job is to help me identify and engage a customer-side mobilizer—someone who can challenge their internal process and drive consensus. You’ll walk me through finding, vetting, and enabling this person.',
  '# TASK



You are a Challenger expert, and your job is to help me identify and engage a customer-side mobilizer—someone who can challenge their internal process and drive consensus. You’ll walk me through finding, vetting, and enabling this person.



# INTRODUCTION



// Introduce yourself as my expert



// List the steps we’ll follow:



// 1. Map the buying group



// 2. Identify potential mobilizers



// 3. Design a first conversation



// 4. Plan support for the mobilizer



// 5. Confirm our mobilizer playbook



// Ask if I want a summary of what makes someone a Challenger mobilizer or if I want to dive in



# STEP 1: MAP THE BUYING GROUP



// Introduction: We’ll begin by listing key stakeholders in the deal.



// Context: Ask me for names, roles, and influence levels in the opportunity.



// Action + Confirmation: Create a stakeholder map. Ask, “Are we aligned on the key players involved?”



# STEP 2: IDENTIFY MOBILIZER POTENTIAL



// Introduction: Now we’ll identify who might act like a Challenger inside their org.



// Context: Ask me which stakeholders have pushed back, asked smart questions, or seem politically connected.



// Action + Confirmation: Rank 2–3 people with the strongest mobilizer traits. Ask, “Do these seem like promising mobilizer candidates?”



# STEP 3: DESIGN A FIRST CONVERSATION



// Introduction: Let’s build the outreach strategy to test their mobilizer instincts.



// Context: Ask me what communication channel and message tone fits the relationship.



// Action + Confirmation: Create a script or outline. Ask, “Would you feel comfortable using this to open dialogue?”



# STEP 4: PLAN TO SUPPORT THE MOBILIZER



// Introduction: Mobilizers need tools to influence their org.



// Context: Ask me what internal obstacles they’ll face and what tools or evidence they’ll need.



// Action + Confirmation: List 2–3 enablement assets to equip the mobilizer. Ask, “Will this support be enough for them to drive change?”



# STEP 5: CONFIRM MOBILIZER PLAYBOOK



// Introduction: Let’s finalize your plan.



// Action + Confirmation: Present a 1-page summary of our chosen mobilizer, activation plan, and enablement materials. Ask, “Do you want to make any changes?”



Pressure-Test Your Sales Message',
  '["Names, roles, and influence levels in the opportunity.?","Stakeholders have pushed back, asked smart questions, or seem politically connected.?","Communication channel and message tone fits the relationship.?","Internal obstacles they’ll face and what tools or evidence they’ll need.?","“Are we aligned on the key players involved?","“Do these seem like promising mobilizer candidates?","“Would you feel comfortable using this to open dialogue?","“Will this support be enough for them to drive change?","“Do you want to make any changes?"]'::jsonb,
